const timeoutId = setTimeout(() => {
  console.log("Po 2 sekundach");
}, 2000);

clearTimeout(timeoutId); // anulowanie ZANIM zdazy sie wykonac - "Po 2 sekundach" NIGDY sie nie pojawi

let count = 0;
const intervalId = setInterval(() => {
  count++;
  console.log("Tick:", count);
  if (count >= 5) clearInterval(intervalId); // zatrzymanie SAMEGO SIEBIE
}, 500);

setInterval(() => {
  console.log("Tick");
}, 1000);
// BRAK jakiegokolwiek clearInterval - dziala W NIESKONCZONOSC!

let count = 0;
const id = setInterval(() => {
  console.log("Tick");
  count++;
  if (count >= 10) clearInterval(id); // POPRAWNIE - jawny warunek stopu
}, 1000);

exercises.solution:
const id = setTimeout(() => console.log("Czesc"), 3000);
clearTimeout(id);
// "Czesc" NIGDY sie nie pojawi, bo anulowano PRZED wykonaniem

const intervalId = setInterval(() => console.log("Tick"), 1000);
setTimeout(() => clearInterval(intervalId), 5000);
// po 5 sekundach interval zostanie zatrzymany

let licznik = 0;
const id = setInterval(() => {
  licznik++;
  console.log(licznik);
  if (licznik >= 5) clearInterval(id);
}, 1000);

// setTimeout NIE jest czescia samego jezyka JavaScript, tylko Web API/
// Node.js API - wywolanie setTimeout(fn, 0) 'odklada' fn do specjalnej
// kolejki (task queue), zamiast wykonac je natychmiast. Silnik
// JavaScript jest JEDNOWATKOWY - musi najpierw dokonczyc caly BIEZACY
// kod (az stos wywolan bedzie pusty), zanim moze 'wyciagnac' fn z
// kolejki i je uruchomic. Dlatego setTimeout(fn, 0) oznacza 'wykonaj fn
// jak najszybciej, ale dopiero PO zakonczeniu calego biezacego kodu',
// a nie 'natychmiast, w trakcie'.
